1	/**
2	 * Tunnel geometry generated from course-aligned "tube paths", so walls, rings and nozzles follow the
3	 * 04 slide, the 06 arch and the full 07 plunge with no seams.
4	 *  - courseTubePath:   tube centred on the course itself (chute, gold ring pipe)
5	 *  - straightTubePath: tube on a low-pass-filtered axis of the course (05–07): the tunnel stays
6	 *    straight with concentric rings converging to one vanishing point (refs 05/07) while the stream
7	 *    winds inside it. Radius/depth adapt so the floor always stays below the winding stream, and the
8	 *    axis converges exactly onto the course at both ends (04 pipe junction, 08 chamber inlet).
9	 */
10	import * as THREE from 'three';
11	import type { Course } from './course';
12	
13	export interface Frame { pos: THREE.Vector3; tan: THREE.Vector3; up: THREE.Vector3; right: THREE.Vector3 }
14	
15	export interface TubePath {
16	  frame(s: number): Frame;
17	  radius(s: number): number;
18	  /** distance from the water point on the axis down to the tube bottom */
19	  depth(s: number): number;
20	}
21	
22	export function courseTubePath(course: Course, radius: (s: number) => number, depth: number | ((s: number) => number) = 0.9): TubePath {
23	  return {
24	    frame: (s) => course.sample(s),
25	    radius,
26	    depth: typeof depth === 'number' ? () => depth : depth,
27	  };
28	}
29	
30	export function straightTubePath(
31	  course: Course,
32	  s0: number,
33	  s1: number,
34	  opts: { window: number; taper: number; baseRadius: (s: number) => number },
35	): TubePath {
36	  const ds = 0.5;
37	  const n = Math.ceil((s1 - s0) / ds) + 1;
38	  const S = (i: number) => Math.min(s1, s0 + i * ds);
39	  const axis: THREE.Vector3[] = [];
40	  const cp: THREE.Vector3[] = [];
41	  for (let i = 0; i < n; i++) cp.push(course.sample(S(i)).pos.clone());
42	  for (let i = 0; i < n; i++) {
43	    const s = S(i);
44	    const taper = THREE.MathUtils.smoothstep(s, s0, s0 + opts.taper) * (1 - THREE.MathUtils.smoothstep(s, s1 - opts.taper, s1));
45	    const W = opts.window * taper;
46	    const k = Math.round(W / ds);
47	    let x = 0, z = 0, wsum = 0;
48	    for (let j = i - k; j <= i + k; j++) {
49	      const jj = THREE.MathUtils.clamp(j, 0, n - 1);
50	      const w = k === 0 ? 1 : 1 - Math.abs(j - i) / (k + 1);
51	      x += cp[jj].x * w; z += cp[jj].z * w; wsum += w;
52	    }
53	    axis.push(new THREE.Vector3(x / wsum, cp[i].y, z / wsum));
54	  }
55	  const frames: Frame[] = axis.map((p, i) => {
56	    const a = axis[Math.max(0, i - 2)], b = axis[Math.min(n - 1, i + 2)];
57	    const tan = b.clone().sub(a).normalize();
58	    const cu = course.sample(S(i)).up;
59	    const up = cu.clone().addScaledVector(tan, -cu.dot(tan)).normalize();
60	    const right = new THREE.Vector3().crossVectors(tan, up).normalize();
61	    return { pos: p, tan, up, right };
62	  });
63	  // radius/depth so the floor stays below the stream edges, dilated + smoothed for a steady tube
64	  const rawR: number[] = [], rawD: number[] = [];
65	  for (let i = 0; i < n; i++) {
66	    const s = S(i);
67	    const d = cp[i].clone().sub(frames[i].pos).dot(frames[i].right);
68	    const X = Math.abs(d) + course.widthAt(s) / 2 + 0.25;
69	    const r = Math.max(opts.baseRadius(s), X + 0.7);
70	    rawR.push(r);
71	    rawD.push(Math.max(0.9, r - Math.sqrt(Math.max(0, r * r - X * X)) + 0.2));
72	  }
73	  const dilate = (arr: number[], k: number) => arr.map((_, i) => { let m = -Infinity; for (let j = i - k; j <= i + k; j++) m = Math.max(m, arr[THREE.MathUtils.clamp(j, 0, n - 1)]); return m; });
74	  const box = (arr: number[], k: number) => arr.map((_, i) => { let a = 0; for (let j = i - k; j <= i + k; j++) a += arr[THREE.MathUtils.clamp(j, 0, n - 1)]; return a / (2 * k + 1); });
75	  const R = box(dilate(rawR, 30), 16);
76	  const D = box(dilate(rawD, 30), 16);
77	  const idx = (s: number) => {
78	    const x = THREE.MathUtils.clamp((s - s0) / ds, 0, n - 1);
79	    const i = Math.min(n - 2, Math.floor(x));
80	    return { i, f: x - i };
81	  };
82	  const lerpArr = (arr: number[], s: number) => { const { i, f } = idx(s); return arr[i] + (arr[i + 1] - arr[i]) * f; };
83	  return {
84	    frame(s) {
85	      const { i, f } = idx(s);
86	      const A = frames[i], B = frames[i + 1];
87	      const pos = A.pos.clone().lerp(B.pos, f);
88	      const tan = A.tan.clone().lerp(B.tan, f).normalize();
89	      const up = A.up.clone().lerp(B.up, f);
90	      up.addScaledVector(tan, -up.dot(tan)).normalize();
91	      return { pos, tan, up, right: new THREE.Vector3().crossVectors(tan, up).normalize() };
92	    },
93	    radius: (s) => lerpArr(R, s),
94	    depth: (s) => lerpArr(D, s),
95	  };
96	}
97	
98	export function tubeCenterAt(path: TubePath, s: number, out = new THREE.Vector3()) {
99	  const f = path.frame(s);
100	  return out.copy(f.pos).addScaledVector(f.up, path.radius(s) - path.depth(s));
101	}
102	
103	export interface TubeGeoOptions {
104	  radial?: number;
105	  step?: number;
106	  vScale?: number;
107	  /** angular range (radians, measured from the bottom) — default full circle */
108	  arc?: number;
109	  /** radius offset (negative = inset toward the axis) */
110	  inset?: number;
111	}
112	
113	export function buildTubeGeometry(path: TubePath, s0: number, s1: number, o: TubeGeoOptions = {}): THREE.BufferGeometry {
114	  const radial = o.radial ?? 48;
115	  const step = o.step ?? 0.6;
116	  const vScale = o.vScale ?? 1;
117	  const arc = o.arc ?? Math.PI * 2;
118	  const rings = Math.max(2, Math.ceil((s1 - s0) / step) + 1);
119	  const pos = new Float32Array(rings * (radial + 1) * 3);
120	  const nor = new Float32Array(rings * (radial + 1) * 3);
121	  const uv = new Float32Array(rings * (radial + 1) * 2);
122	  const c = new THREE.Vector3();
123	  const d = new THREE.Vector3();
124	  for (let i = 0; i < rings; i++) {
125	    const s = s0 + ((s1 - s0) * i) / (rings - 1);
126	    const f = path.frame(s);
127	    const r = path.radius(s) + (o.inset ?? 0);
128	    c.copy(f.pos).addScaledVector(f.up, path.radius(s) - path.depth(s));
129	    for (let j = 0; j <= radial; j++) {
130	      const th = -Math.PI / 2 - arc / 2 + (j / radial) * arc; // centred on the bottom
131	      d.copy(f.right).multiplyScalar(Math.cos(th)).addScaledVector(f.up, Math.sin(th));
132	      const k = i * (radial + 1) + j;
133	      pos[k * 3] = c.x + d.x * r;
134	      pos[k * 3 + 1] = c.y + d.y * r;
135	      pos[k * 3 + 2] = c.z + d.z * r;
136	      nor[k * 3] = -d.x; nor[k * 3 + 1] = -d.y; nor[k * 3 + 2] = -d.z;
137	      uv[k * 2] = j / radial;
138	      uv[k * 2 + 1] = s / vScale;
139	    }
140	  }
141	  const idx: number[] = [];
142	  for (let i = 0; i < rings - 1; i++) {
143	    for (let j = 0; j < radial; j++) {
144	      const a = i * (radial + 1) + j, b = a + radial + 1;
145	      idx.push(a, b, a + 1, b, b + 1, a + 1);
146	    }
147	  }
148	  const g = new THREE.BufferGeometry();
149	  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
150	  g.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
151	  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
152	  g.setIndex(idx);
153	  g.computeBoundingSphere();
154	  return g;
155	}
156	
157	/** Instanced thick gold ring ribs placed perpendicular to the tube every `spacing` units. */
158	export function buildRings(
159	  path: TubePath,
160	  s0: number,
161	  s1: number,
162	  spacing: number,
163	  material: THREE.Material,
164	  opts: { tube?: number; double?: boolean; inset?: number; extra?: number } = {},
165	): THREE.InstancedMesh {
166	  const tube = opts.tube ?? 0.075;
167	  const geo = new THREE.TorusGeometry(1, tube, 14, 72);
168	  const n = Math.max(1, Math.floor((s1 - s0) / spacing) + 1) * (opts.double ? 2 : 1);
169	  const mesh = new THREE.InstancedMesh(geo, material, n);
170	  const m = new THREE.Matrix4();
171	  const q = new THREE.Quaternion();
172	  const basis = new THREE.Matrix4();
173	  const c = new THREE.Vector3();
174	  let k = 0;
175	  for (let s = s0; s <= s1 + 1e-6 && k < n; s += spacing) {
176	    for (let dbl = 0; dbl < (opts.double ? 2 : 1); dbl++) {
177	      const ss = s + dbl * spacing * 0.16;
178	      const f = path.frame(ss);
179	      const r = path.radius(ss) - (opts.inset ?? 0.05) + (opts.extra ?? 0);
180	      c.copy(f.pos).addScaledVector(f.up, path.radius(ss) - path.depth(ss));
181	      basis.makeBasis(f.right, f.up, f.tan);
182	      q.setFromRotationMatrix(basis);
183	      const sc = dbl ? r * 0.985 : r;
184	      m.compose(c, q, new THREE.Vector3(sc, sc, sc * (dbl ? 0.6 : 1)));
185	      mesh.setMatrixAt(k++, m);
186	    }
187	  }
188	  mesh.count = k;
189	  mesh.instanceMatrix.needsUpdate = true;
190	  mesh.frustumCulled = false;
191	  return mesh;
192	}
193	
194	/** Half-dome wall "lids"/spray heads mounted on the upper tube walls (refs 05–07). */
195	export function buildNozzles(
196	  path: TubePath,
197	  s0: number,
198	  s1: number,
199	  spacing: number,
200	  domeMat: THREE.Material,
201	  rimMat: THREE.Material,
202	  opts: { angleDeg?: number; size?: number } = {},
203	): THREE.Group {
204	  const group = new THREE.Group();
205	  const size = opts.size ?? 1.6;
206	  const dome = new THREE.SphereGeometry(1, 28, 12, 0, Math.PI * 2, 0, Math.PI / 2);
207	  dome.scale(1.25, 0.55, 0.85);
208	  const rim = new THREE.TorusGeometry(1, 0.1, 10, 40);
209	  rim.rotateX(Math.PI / 2);
210	  rim.scale(1.25, 1, 0.85);
211	  const nDomes = Math.floor((s1 - s0) / spacing) + 1;
212	  const imDome = new THREE.InstancedMesh(dome, domeMat, nDomes);
213	  const imRim = new THREE.InstancedMesh(rim, rimMat, nDomes);
214	  const m = new THREE.Matrix4();
215	  const basis = new THREE.Matrix4();
216	  const q = new THREE.Quaternion();
217	  const c = new THREE.Vector3();
218	  const dir = new THREE.Vector3();
219	  let k = 0;
220	  for (let s = s0; s <= s1 && k < nDomes; s += spacing, k++) {
221	    const f = path.frame(s);
222	    const r = path.radius(s);
223	    const side = k % 2 === 0 ? 1 : -1;
224	    const ang = THREE.MathUtils.degToRad(opts.angleDeg ?? 32);
225	    tubeCenterAt(path, s, c);
226	    dir.copy(f.right).multiplyScalar(Math.cos(ang) * side).addScaledVector(f.up, Math.sin(ang)).normalize();
227	    const p = c.clone().addScaledVector(dir, r * 0.985);
228	    const inward = dir.clone().negate();
229	    const xAxis = new THREE.Vector3().crossVectors(inward, f.tan).normalize();
230	    const zAxis = new THREE.Vector3().crossVectors(xAxis, inward).normalize();
231	    basis.makeBasis(xAxis, inward, zAxis);
232	    q.setFromRotationMatrix(basis);
233	    m.compose(p, q, new THREE.Vector3(size, size, size));
234	    imDome.setMatrixAt(k, m);
235	    imRim.setMatrixAt(k, m);
236	  }
237	  imDome.count = imRim.count = k;
238	  imDome.frustumCulled = imRim.frustumCulled = false;
239	  group.add(imDome, imRim);
240	  return group;
241	}
