1	/**
2	 * Washer-world materials: procedural perforated magenta metal (round holes for drums, circumferential
3	 * slots for tunnels), thick reflective gold, chrome, glass — all PBR (MeshStandardMaterial) so they pick
4	 * up the candy PMREM environment, with shader patches for the perforations and glow.
5	 */
6	import * as THREE from 'three';
7	
8	export interface PerforatedOptions {
9	  /** base metal colour */
10	  color?: THREE.ColorRepresentation;
11	  /** colour of the hole interiors */
12	  holeColor?: THREE.ColorRepresentation;
13	  /** 0 = round holes (drum), 1 = slots elongated along u (tunnel rings) */
14	  slot?: number;
15	  /** pattern repeats: holes around u (per 0..1) and per uv-unit along v */
16	  repeatU?: number;
17	  repeatV?: number;
18	  /** hole size relative to its cell (0..1) */
19	  holeSize?: number;
20	  emissive?: THREE.ColorRepresentation;
21	  emissiveIntensity?: number;
22	  metalness?: number;
23	  roughness?: number;
24	  side?: THREE.Side;
25	  /** bright stripe highlights running along v (tunnel light streaks) */
26	  streaks?: number;
27	}
28	
29	export function perforatedMetal(o: PerforatedOptions = {}): THREE.MeshStandardMaterial {
30	  const mat = new THREE.MeshStandardMaterial({
31	    color: o.color ?? '#d13fd6',
32	    metalness: o.metalness ?? 0.72,
33	    roughness: o.roughness ?? 0.26,
34	    emissive: new THREE.Color(o.emissive ?? '#9a1fa8'),
35	    emissiveIntensity: o.emissiveIntensity ?? 0.26,
36	    side: o.side ?? THREE.BackSide,
37	    envMapIntensity: 1.0,
38	  });
39	  const uniforms = {
40	    uHoleColor: { value: new THREE.Color(o.holeColor ?? '#2b0640') },
41	    uSlot: { value: o.slot ?? 1 },
42	    uRepeat: { value: new THREE.Vector2(o.repeatU ?? 64, o.repeatV ?? 1.2) },
43	    uHoleSize: { value: o.holeSize ?? 0.42 },
44	    uStreaks: { value: o.streaks ?? 0.35 },
45	  };
46	  mat.userData.perfUniforms = uniforms;
47	  mat.onBeforeCompile = (shader) => {
48	    Object.assign(shader.uniforms, uniforms);
49	    shader.vertexShader = shader.vertexShader
50	      .replace('#include <common>', '#include <common>\nvarying vec2 vPerfUv;')
51	      .replace('#include <uv_vertex>', '#include <uv_vertex>\nvPerfUv = uv;');
52	    shader.fragmentShader = shader.fragmentShader
53	      .replace(
54	        '#include <common>',
55	        `#include <common>
56	varying vec2 vPerfUv;
57	uniform vec3 uHoleColor; uniform float uSlot; uniform vec2 uRepeat; uniform float uHoleSize; uniform float uStreaks;
58	float perfMask(vec2 uv, out float rim){
59	  vec2 g = uv * uRepeat;
60	  float row = floor(g.y);
61	  g.x += mod(row, 2.0) * 0.5;          // staggered rows
62	  vec2 f = fract(g) - 0.5;
63	  vec2 hs = mix(vec2(uHoleSize*0.5), vec2(uHoleSize*0.62, uHoleSize*0.24), uSlot);
64	  vec2 q = abs(f) - hs + min(hs.x, hs.y);
65	  float d = length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - min(hs.x, hs.y);
66	  float aa = fwidth(d) * 1.2 + 1e-4;
67	  rim = smoothstep(0.06, 0.0, abs(d - 0.02)) * step(0.0, f.y);  // light catching the lower lip
68	  return 1.0 - smoothstep(-aa, aa, d); // 1 inside hole
69	}`,
70	      )
71	      .replace(
72	        '#include <color_fragment>',
73	        `#include <color_fragment>
74	float perfRim; float perfHole = perfMask(vPerfUv, perfRim);
75	float streak = pow(0.5 + 0.5 * sin(vPerfUv.x * 6.2831 * 9.0 + 1.3), 18.0) * uStreaks;
76	diffuseColor.rgb = mix(diffuseColor.rgb * (1.0 + streak), uHoleColor, perfHole);`,
77	      )
78	      .replace(
79	        '#include <metalnessmap_fragment>',
80	        `#include <metalnessmap_fragment>
81	metalnessFactor *= (1.0 - perfHole);`,
82	      )
83	      .replace(
84	        '#include <roughnessmap_fragment>',
85	        `#include <roughnessmap_fragment>
86	roughnessFactor = mix(roughnessFactor, 0.9, perfHole);`,
87	      )
88	      .replace(
89	        '#include <emissivemap_fragment>',
90	        `#include <emissivemap_fragment>
91	totalEmissiveRadiance = totalEmissiveRadiance * (1.0 - perfHole) + vec3(1.0, 0.82, 1.0) * perfRim * 0.55 * (1.0 - perfHole) + vec3(1.0,0.9,1.0) * streak * 0.6;`,
92	      );
93	  };
94	  mat.customProgramCacheKey = () => 'perf-v1';
95	  return mat;
96	}
97	
98	export function gold(opts: { roughness?: number; emissive?: number; color?: THREE.ColorRepresentation } = {}): THREE.MeshStandardMaterial {
99	  return new THREE.MeshStandardMaterial({
100	    color: opts.color ?? '#ffcf4d',
101	    metalness: 1,
102	    roughness: opts.roughness ?? 0.2,
103	    emissive: new THREE.Color('#c98a00'),
104	    emissiveIntensity: opts.emissive ?? 0.38,
105	    envMapIntensity: 1.6,
106	  });
107	}
108	
109	/** gold with ribbed "ring pipe" bands along v (scene 04 tunnel) */
110	export function goldRibbed(repeatV = 1.6): THREE.MeshStandardMaterial {
111	  const m = gold({ roughness: 0.18, emissive: 0.5 });
112	  m.side = THREE.BackSide;
113	  const uniforms = { uRibs: { value: repeatV } };
114	  m.onBeforeCompile = (shader) => {
115	    Object.assign(shader.uniforms, uniforms);
116	    shader.vertexShader = shader.vertexShader
117	      .replace('#include <common>', '#include <common>\nvarying vec2 vRibUv;')
118	      .replace('#include <uv_vertex>', '#include <uv_vertex>\nvRibUv = uv;');
119	    shader.fragmentShader = shader.fragmentShader
120	      .replace('#include <common>', '#include <common>\nvarying vec2 vRibUv; uniform float uRibs;')
121	      .replace(
122	        '#include <color_fragment>',
123	        `#include <color_fragment>
124	float rp = fract(vRibUv.y * uRibs);
125	diffuseColor.rgb *= 0.72 + 0.42 * smoothstep(0.0, 0.5, rp) * smoothstep(1.0, 0.5, rp);`,
126	      )
127	      .replace(
128	        '#include <emissivemap_fragment>',
129	        `#include <emissivemap_fragment>
130	float edge = smoothstep(0.85, 1.0, fract(vRibUv.y * uRibs));
131	totalEmissiveRadiance += vec3(1.0, 0.86, 0.5) * edge * 0.9;`,
132	      );
133	  };
134	  m.customProgramCacheKey = () => 'goldrib-v1';
135	  return m;
136	}
137	
138	export function chrome(): THREE.MeshStandardMaterial {
139	  return new THREE.MeshStandardMaterial({ color: '#efe6ff', metalness: 1, roughness: 0.12, envMapIntensity: 1.5, emissive: '#3a2a55', emissiveIntensity: 0.25 });
140	}
141	
142	export function glass(tint: THREE.ColorRepresentation = '#dfe9ff', opacity = 0.18): THREE.MeshPhysicalMaterial {
143	  return new THREE.MeshPhysicalMaterial({
144	    color: tint,
145	    metalness: 0,
146	    roughness: 0.04,
147	    transmission: 0,
148	    transparent: true,
149	    opacity,
150	    envMapIntensity: 2.2,
151	    side: THREE.DoubleSide,
152	    depthWrite: false,
153	  });
154	}
155	
156	/** soft unlit-ish painted material for the laundry room seen through doors (keeps it bright & airy) */
157	export function painted(color: THREE.ColorRepresentation, emissive = 0.2, roughness = 0.75): THREE.MeshStandardMaterial {
158	  const c = new THREE.Color(color);
159	  return new THREE.MeshStandardMaterial({ color: c, roughness, metalness: 0, emissive: c, emissiveIntensity: emissive });
160	}
161	
162	/** canvas texture helper */
163	export function canvasTexture(w: number, h: number, draw: (g: CanvasRenderingContext2D, w: number, h: number) => void, srgb = true): THREE.CanvasTexture {
164	  const c = document.createElement('canvas');
165	  c.width = w; c.height = h;
166	  draw(c.getContext('2d')!, w, h);
167	  const t = new THREE.CanvasTexture(c);
168	  if (srgb) t.colorSpace = THREE.SRGBColorSpace;
169	  t.anisotropy = 4;
170	  return t;
171	}
