28	const STAGE_ORDER: StageId[] = ['01', '02', '03', '04', '05', '06', '07', '08', '09', '10', '11'];
29	const sm = (a: number, b: number, x: number) => THREE.MathUtils.smoothstep(x, a, b);
30	const lerp = THREE.MathUtils.lerp;
31	
32	/** intro timeline marks (seconds) */
33	const T = { dropEnd: 1.6, doorClose0: 1.9, doorClose1: 2.8, walk0: 3.0, peek: 4.4, cp01: 6.6, spin: 7.4, cp02: 9.1, drain: 11.4, rideStart: 14.0 };
34	/** outro timeline marks */
35	const O = { hide: 0.6, walk0: 0.0, door0: 1.1, door1: 2.1, lean0: 1.9, fold0: 2.7, fold1: 3.7, hold: 6.4, badge: 3.9, cp11: 5.2 };
36	
37	export async function startGame(canvas: HTMLCanvasElement) {
38	  const qs = new URLSearchParams(location.search);
39	  const qaMode = qs.has('qa');
40	  const renderer = createRenderer(canvas, { preserveDrawingBuffer: qaMode });
41	  const dpr = qs.has('dpr') ? Number(qs.get('dpr')) : Math.min(window.devicePixelRatio || 1, 2);
42	  renderer.setPixelRatio(dpr);
43	  const scene = new THREE.Scene();
44	  scene.environment = createCandyEnvironment(renderer);
45	  scene.background = new THREE.Color('#b23fb4');
46	  const fog = new THREE.FogExp2('#ffbde9', 0.0035);
47	  scene.fog = fog;
48	  scene.add(new THREE.HemisphereLight('#fff0ff', '#a33bb8', 1.15));
49	  const sun = new THREE.DirectionalLight('#fff4e6', 1.6);
50	  sun.position.set(0.3, 1, 0.45);
51	  scene.add(sun);
52	  scene.add(sun.target);
53	  const fill = new THREE.PointLight('#ffd8ff', 30, 30, 1.6);
54	  scene.add(fill);
55	
56	  const camera = new THREE.PerspectiveCamera(66, 9 / 16, 0.05, 1200);
57	  const composer = new EffectComposer(renderer);
58	  composer.addPass(new RenderPass(scene, camera));
59	  const bloom = new UnrealBloomPass(new THREE.Vector2(256, 256), 0.2, 0.35, 0.94);
60	  const useBloom = qs.get('bloom') !== '0';
61	  if (useBloom) composer.addPass(bloom);
62	  composer.addPass(new OutputPass());
63	  composer.addPass(createGradePass());
64	
65	  const resize = () => {
66	    const w = canvas.clientWidth || window.innerWidth;
67	    const h = canvas.clientHeight || window.innerHeight;
68	    renderer.setSize(w, h, false);
69	    composer.setSize(w, h);
70	    bloom.resolution.set(w / 2, h / 2);
71	    camera.aspect = w / h;
72	    camera.updateProjectionMatrix();
73	  };
74	  window.addEventListener('resize', resize);
75	  resize();
76	
77	  // ---------------------------------------------------------------- world
78	  const course = new Course();
79	  const env = buildEnvironment(course);
80	  scene.add(env.group);
81	  const water = await loadWater(course);
82	  scene.add(water.group);
83	  const benny = await loadBennyRuntime();
84	  scene.add(benny.root);
85	  const girl = await loadGirlRuntime();
86	  const coins = createCoins(course);
87	  scene.add(coins.group);
88	  // debug: ?hide=water,benny,coins,drumA,basin,tubes,chamber
89	  const hidden = new Set((qs.get('hide') ?? '').split(',').filter(Boolean));
90	  if (hidden.has('water')) water.group.visible = false;
91	  if (hidden.has('coins')) coins.group.visible = false;
92	  const zoneHidden = (k: string) => hidden.has(k);
93	  const hud = createHud();
94	  const input = createInput(canvas);
95	  const rideCam = new RideCamera(course);
96	  rideCam.axis = env.tubeAxis;
97	
98	  // ---------------------------------------------------------------- state
99	  const st = {
100	    mode: 'intro' as Mode,
101	    t: 0, // time within the current mode
102	    clock: 0, // global animation time (shaders)
103	    frozen: null as number | null, // QA: freeze shader time
104	    s: 0,
105	    lat: 0,
106	    vlat: 0,
107	    coins: START_COINS,
108	    hearts: 5,
109	    paused: false,
110	    stage: '01' as StageId,
111	    bumpCooldown: 0,
112	    edgeTime: 0,
113	    twirl: 0,
114	    respawns: 0,
115	    log: [] as { t: number; s: number; y: number; stage: StageId }[],
116	  };
117	
118	  const stageOf = (s: number): StageId => course.stageAtS(s).id;
119	
120	  const setStage = (id: StageId) => {
121	    if (st.stage === id) return;
122	    st.stage = id;
123	    hud.setStage(id);
124	    updateZones();
125	  };
126	
127	  const zoneRanges: Record<keyof typeof env.zones, [StageId, StageId]> = {
128	    drumA: ['01', '02'],
129	    basin: ['02', '05'],
130	    tubes: ['03', '09'],
131	    chamber: ['07', '11'],
132	  };
133	  const updateZones = () => {
134	    const i = STAGE_ORDER.indexOf(st.stage);
135	    for (const [k, [a, b]] of Object.entries(zoneRanges)) {
136	      env.zones[k as keyof typeof env.zones].visible = !zoneHidden(k) && i >= STAGE_ORDER.indexOf(a) && i <= STAGE_ORDER.indexOf(b);
137	    }
138	    const inDrum = i <= 1;
139	    fog.density = inDrum ? 0.0015 : i >= 7 ? 0.0025 : 0.0035;
140	  };
141	
142	  // girl placement helpers (she lives in laundry-room local frames)
143	  const placeGirl = (room: 'A' | 'C', local: THREE.Vector3, yaw: number) => {
144	    const anchor = room === 'A' ? env.roomA.anchor : env.roomC.anchor;
145	    if (girl.root.parent !== anchor) anchor.add(girl.root);
146	    girl.root.position.copy(local);
147	    girl.root.rotation.set(0, yaw, 0);
148	  };
149	
150	  const bennyPose = (s: number, lat: number, time: number, out: { pos: THREE.Vector3; quat: THREE.Quaternion }) => {
151	    const f = course.sample(s);
152	    const h = water.surfaceHeight(s, lat, time);
153	    out.pos.copy(f.pos).addScaledVector(f.right, lat).addScaledVector(f.up, h + benny.radius * 0.55);
154	    const m = new THREE.Matrix4().makeBasis(new THREE.Vector3().crossVectors(f.up, f.tan).normalize(), f.up, f.tan);
155	    out.quat.setFromRotationMatrix(m);
156	    return f;
157	  };
158	
159	  const pose = { pos: new THREE.Vector3(), quat: new THREE.Quaternion() };
160	  const tmpV = new THREE.Vector3();
161	  const doorAOpen = -1.9, doorCOpen = -1.95;
162	
163	  // ---------------------------------------------------------------- intro (01–02)
164	  const introUpdate = (dt: number) => {
165	    const t = st.t;
166	    const wc = (water as unknown as { controls?: { drumSwirl: number; drumAgitation: number; outro: number } }).controls;
167	    if (wc) {
168	      wc.drumAgitation = 0.35 + 0.65 * sm(T.spin - 0.5, T.spin + 0.8, t);
169	      wc.drumSwirl = sm(T.spin, T.spin + 1.2, t) * (1 - sm(T.drain + 0.5, T.rideStart, t));
170	      wc.outro = 0;
171	    }
172	    const dA = WORLD.drumA;
173	    const start = course.sample(0).pos;
174	    // --- girl: drop the load, close the door, walk away at normal pace (never looks back)
175	    const spots = env.roomA.spots;
176	    if (t < T.walk0) {
177	      placeGirl('A', new THREE.Vector3(1.2, spots.nearDoor.y, 7.6), Math.PI);
178	      girl.play(t < T.dropEnd ? 'dropLoad' : 'closeDoor', { fade: 0.25 });
179	    } else {
180	      const k = THREE.MathUtils.clamp((t - T.walk0 - 0.35) / 4.6, 0, 1);
181	      const from = new THREE.Vector3(1.2, spots.nearDoor.y, 7.6);
182	      const p = from.clone().lerp(spots.exitLeft, k);
183	      const dir = spots.exitLeft.clone().sub(from);
184	      const yawWalk = Math.atan2(dir.x, dir.z);
185	      const turn = sm(T.walk0, T.walk0 + 0.6, t);
186	      placeGirl('A', p, lerp(Math.PI, yawWalk, turn));
187	      girl.play('walk', { fade: 0.3 });
188	    }
189	    // --- door A
190	    env.doorA.rotation.y = lerp(doorAOpen, 0, sm(T.doorClose0, T.doorClose1, t));
191	    // --- towel bundle flies from her hands into the drum, Benny hidden inside
192	    const handW = girl.handR.getWorldPosition(tmpV).clone();
193	    const k = sm(0.35, T.dropEnd, t);
194	    const towelRest = start.clone().add(new THREE.Vector3(0.15, -1.25, 0.05));
195	    const arc = handW.clone().lerp(towelRest, k);
196	    arc.y += Math.sin(k * Math.PI) * 1.2;
197	    let sB = 0;
198	    if (t >= T.spin && st.stage === '01') { st.stage = '02'; hud.setStage('02'); }
199	    if (t < T.spin) {
200	      env.drumTowel.mesh.position.copy(t < 0.35 ? handW : arc);
201	      env.drumTowel.mesh.rotation.set(0, 0.4, 0);
202	      env.drumTowel.setBundle(1);
203	      env.drumTowel.mesh.scale.setScalar(0.62);
204	      // Benny inside the bundle; peeks out only once she has turned away
205	      const peek = sm(T.peek, T.peek + 0.7, t);
206	      benny.root.visible = peek > 0.02;
207	      benny.setExpression('peek');
208	      bennyPose(0, 0, st.clock, pose);
209	      benny.root.position.copy(start).add(new THREE.Vector3(0, -1.0 + 1.35 * peek, 0));
210	      benny.root.quaternion.setFromEuler(new THREE.Euler(0, Math.PI + 0.25, 0)); // facing the camera (inside drum)
211	      benny.update(dt, { swim: 0, steer: 0, speed: 0, time: st.clock });
212	    } else {
213	      // spin: tumble along the 02 helix, then the chute
214	      const u = sm(T.spin, T.rideStart, t);
215	      const s03 = course.stage('03').s0;
216	      sB = s03 * (t < T.drain ? 0.55 * sm(T.spin, T.drain, t) : 0.55 + 0.45 * sm(T.drain, T.rideStart, t));
217	      void u;
218	      benny.root.visible = true;
219	      benny.setExpression(t < T.drain + 1.2 ? 'dizzy' : 'happy');
220	      const f = bennyPose(sB, 0, st.clock, pose);
221	      // inside Drum A the swirl carries him along the helix itself (no ribbon surface there yet)
222	      const inDrum = 1 - sm(T.drain - 0.4, T.drain + 0.6, t);
223	      // the swirl lifts him toward the middle of the drum while he tumbles (ref 02), then he drops to the drain
224	      const hp = course.sample(sB).pos;
225	      const toAxis = sm(T.spin, T.spin + 1.0, t) * (1 - sm(T.drain - 1.6, T.drain - 0.2, t)) * 0.45;
226	      hp.x *= 1 - toAxis; hp.y = hp.y + (0.2 - hp.y) * toAxis;
227	      benny.root.position.copy(pose.pos).lerp(hp, inDrum);
228	      const tumble = sm(T.rideStart - 1.0, T.rideStart, t);
229	      // tumble = rolling cartwheels seen by the camera: face the lens, roll around the view axis
230	      const toCam = cam02(benny.root.position).pos.clone().sub(benny.root.position).normalize();
231	      const face = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 0, 1), toCam);
232	      const roll = new THREE.Quaternion().setFromAxisAngle(toCam, Math.sin(t * 1.7) * 0.9 + t * 1.1);
233	      const wobble = new THREE.Quaternion().setFromEuler(new THREE.Euler(Math.sin(t * 2.3) * 0.35, Math.sin(t * 1.9) * 0.4, 0));
234	      const spinQ = roll.multiply(face).multiply(wobble);
235	      benny.root.quaternion.copy(spinQ).slerp(pose.quat, tumble);
236	      benny.update(dt, { swim: 0.4, steer: 0, speed: 8, time: st.clock, tumble: tumble < 0.99 });
237	      // towel lags behind and unravels in the drum
238	      const sT = Math.max(0, sB - 2.6);
239	      const ft = course.sample(Math.min(sT, course.marks['02_drain'] - 1));
240	      env.drumTowel.mesh.position.copy(ft.pos).addScaledVector(ft.up, -0.4);
241	      env.drumTowel.mesh.rotation.set(t * 0.8, t * 0.5, 0.3);
242	      env.drumTowel.setBundle(lerp(1, 0.45, sm(T.spin, T.cp02, t)));
243	      env.drumTowel.mesh.scale.setScalar(lerp(0.62, 0.8, sm(T.spin, T.cp02, t)));
244	      void f;
245	    }
246	    st.s = sB;
247	    // --- floating laundry
248	    const sw = t < T.spin ? 0 : (t - T.spin) * 1.6;
249	    env.laundry.sock.position.set(Math.cos(2.3 + sw) * 2.2 - 0.6, -1.5 + Math.sin(st.clock * 1.3) * 0.15 + Math.sin(2.3 + sw) * (t < T.spin ? 0 : 1.6), 0.6 - sw * 0.25);
250	    env.laundry.sock.rotation.set(0.3 + sw, 0.6, 0.9 + st.clock * 0.3);
251	    env.laundry.shirt.position.set(-2.0 + Math.cos(0.4 + sw) * (t < T.spin ? 0 : 2.0), -1.6 + Math.sin(st.clock * 1.1 + 1) * 0.15 + (t < T.spin ? 0 : Math.sin(0.4 + sw) * 2.2), 0.9 - sw * 0.2);
252	    env.laundry.shirt.rotation.set(-1.15 + sw * 0.7, 0.2 + sw, 0.15);
253	    env.laundry.shirt.scale.setScalar(0.62);
254	    env.laundry.sock.scale.setScalar(0.62);
255	    // --- cameras
256	    if (t < T.spin + 0.6) {
257	      // 01: inside the drum looking out through the door, Benny peeking in the foreground
258	      camera.position.set(0.85, -1.05, -6.05);
259	      camera.up.set(0, 1, 0);
260	      camera.lookAt(-0.05, -0.2, dA.zDoor);
261	      setFov(64);
262	    } else if (t < T.drain) {
263	      // 02: tumbling with the swirl; the door ring above (deterministic blend from the 01 shot)
264	      const c2 = cam02(benny.root.position);
265	      const k2 = sm(T.spin + 0.6, T.spin + 1.6, t);
266	      const p01 = new THREE.Vector3(0.85, -1.05, -6.05), l01 = new THREE.Vector3(-0.05, -0.2, dA.zDoor);
267	      camera.position.copy(p01.lerp(c2.pos, k2));
268	      camera.up.set(0, 1, 0);
269	      camera.lookAt(l01.lerp(c2.look, k2));
270	      setFov(lerp(64, 68, k2));
271	    } else {
272	      // chute chase cam, blending into the ride camera framing for 03
273	      const kk = sm(T.drain, T.rideStart, t);
274	      const back = course.pointAt(Math.max(0, sB - 3.6), 0, 1.7);
275	      const look = course.pointAt(sB + 4, 0, 0.2);
276	      const rp = new THREE.Vector3(), rt = new THREE.Vector3(), ru = new THREE.Vector3();
277	      rideCam.desired(Math.max(course.stage('03').s0, sB), 0, rp, rt, ru);
278	      camera.position.lerp(back.lerp(rp, kk * kk), 0.15);
279	      camera.up.set(0, 1, 0);
280	      camera.lookAt(look.lerp(rt, kk * kk));
281	      setFov(lerp(66, 64, kk));
282	    }
283	    if (t >= T.rideStart) startRide();
284	  };
285	
286	  /** 02 camera: between Benny and the drum's back wall, looking past him to the door ring */
287	  const cam02 = (b: THREE.Vector3) => {
288	    const dA = WORLD.drumA;
289	    const door = new THREE.Vector3(0, 0.3, dA.zDoor);
290	    const away = b.clone().sub(door).normalize();
291	    const pos = b.clone().addScaledVector(away, 3.0).add(new THREE.Vector3(0, 0.35, 0));
292	    const rr = Math.hypot(pos.x, pos.y);
293	    if (rr > 2.7) { pos.x *= 2.7 / rr; pos.y *= 2.7 / rr; }
294	    pos.y = Math.max(pos.y, dA.waterY + 1.0);
295	    pos.z = THREE.MathUtils.clamp(pos.z, dA.zBack + 0.4, dA.zDoor - 1);
296	    const look = b.clone().lerp(door, 0.22).add(new THREE.Vector3(0, 0.45, 0));
297	    return { pos, look };
298	  };
299	
300	  const setFov = (f: number) => {
301	    if (Math.abs(camera.fov - f) > 0.01) { camera.fov = f; camera.updateProjectionMatrix(); }
302	  };
303	
304	  const startRide = () => {
305	    st.mode = 'ride';
306	    st.t = 0;
307	    st.s = course.stage('03').s0;
308	    st.lat = 0;
309	    hud.setVisible(true);
310	    setStage('03');
311	    rideCam.pos.copy(camera.position);
312	    rideCam.target.copy(camera.position).add(camera.getWorldDirection(new THREE.Vector3()).multiplyScalar(10));
313	    rideCam.fov = camera.fov;
314	    hud.showHint('Drag or hold left / right to steer');
315	    setTimeout(() => hud.showHint(null), 3500);
316	  };
317	
318	  // ---------------------------------------------------------------- ride (03–10)
319	  const rideUpdate = (dt: number) => {
320	    input.update(dt);
321	    const stg = course.stageAtS(st.s);
322	    const speed = course.prop('speed', st.s);
323	    st.s = Math.min(course.stage('11').s0, st.s + speed * dt);
324	    const halfW = course.widthAt(st.s) / 2;
325	    const safe = halfW - 0.75;
326	    st.vlat += (input.steer * 7.5 - st.vlat) * Math.min(1, dt * 8);
327	    st.lat = THREE.MathUtils.clamp(st.lat + st.vlat * dt, -halfW + 0.55, halfW - 0.55);
328	    // foam-wall bump → lose a heart (with cooldown), bounce back toward the centre
329	    st.bumpCooldown = Math.max(0, st.bumpCooldown - dt);
330	    if (Math.abs(st.lat) > safe) st.edgeTime += dt; else st.edgeTime = 0;
331	    if (st.edgeTime > 0.6 && st.bumpCooldown <= 0) {
332	      st.hearts = Math.max(0, st.hearts - 1);
333	      hud.setHearts(st.hearts);
334	      hud.flashHurt();
335	      st.bumpCooldown = 1.6;
336	      st.vlat = -Math.sign(st.lat) * 9;
337	      water.splash(benny.root.position, course.sample(st.s).up, 1);
338	      if (st.hearts === 0) {
339	        // restart this stage with full hearts (checkpoint), coins kept
340	        st.hearts = 5;
341	        hud.setHearts(5);
342	        st.s = stg.s0;
343	        st.lat = 0;
344	        st.respawns++;
345	      }
346	    }
347	    // coins
348	    const got = coins.update(st.clock, dt, st.s, st.lat);
349	    if (got) { st.coins += got * COIN_VALUE; hud.setCoins(st.coins); }
350	    setStage(stageOf(st.s));
351	    // Benny
352	    const f = bennyPose(st.s, st.lat, st.clock, pose);
353	    benny.root.position.copy(pose.pos);
354	    const lean = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 0, 1), -input.steer * 0.25);
355	    // 03 whirlpool twirl: Benny spins around his up axis while riding the vortex
356	    st.twirl = st.stage === '03' ? st.twirl + dt * 2.2 : st.twirl * Math.max(0, 1 - dt * 3);
357	    const tw = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), st.stage === '03' ? Math.PI + Math.sin(st.twirl) * 0.9 : 0);
358	    benny.root.quaternion.copy(pose.quat).multiply(tw).multiply(lean);
359	    benny.root.visible = true;
360	    benny.setExpression('happy');
361	    benny.update(dt, { swim: 1, steer: input.steer, speed, time: st.clock });
362	    water.wake(pose.pos, f.tan, f.right, speed, dt);
363	    // camera
364	    rideCam.update(dt, st.s, st.lat, camera);
365	    // towel: folded in 08/09, lifted into a tent as the stream reaches it (late 09 → 10)
366	    env.towel.setTent(sm(course.stage('09').s1 - 6, course.stage('10').s0 + 2, st.s));
367	    // girl at the counter behind the door glass in 10 (back turned — never sees Benny)
368	    if (st.stage === '09' || st.stage === '10') {
369	      placeGirl('C', env.roomC.spots.table.clone(), 0.25);
370	      girl.play('laundryCounter', { fade: 0.3 });
371	    }
372	    env.doorC.rotation.y = 0;
373	    st.log.push({ t: st.clock, s: st.s, y: benny.root.position.y, stage: st.stage });
374	    if (st.log.length > 20000) st.log.shift();
375	    if (st.s >= course.stage('11').s0 - 0.01) startOutro();
376	  };
377	
378	  // ---------------------------------------------------------------- outro (11)
379	  const startOutro = () => {
380	    st.mode = 'outro';
381	    st.t = 0;
382	    setStage('11');
383	  };
384	  const outroUpdate = (dt: number) => {
385	    const t = st.t;
386	    const sEnd = course.stage('11').s0;
387	    // Benny finishes sliding under the tent and is hidden (still there, just unseen)
388	    bennyPose(sEnd, 0, st.clock, pose);
389	    benny.root.position.copy(pose.pos).addScaledVector(course.sample(sEnd).tan, 0.6 * sm(0, O.hide, t));
390	    benny.root.quaternion.copy(pose.quat);
391	    benny.root.visible = t < O.hide;
392	    benny.update(dt, { swim: 0.2, steer: 0, speed: 2, time: st.clock });
393	    // door opens outward
394	    env.doorC.rotation.y = lerp(0, doorCOpen, sm(O.door0, O.door1, t));
395	    // girl: from the folding table to the door, leans in through it with her palms on the towel,
396	    // folds it over Benny and draws it toward herself (never sees him — he is inside the fold)
397	    const P0 = WORLD.platform;
398	    const towelZ = lerp(P0.center.z - 1.0, P0.center.z - 3.4, sm(O.fold0, O.fold1, t));
399	    env.towel.mesh.position.set(P0.center.x, P0.topY, towelZ);
400	    // palms of 'leanReachTowel' are at (±3.64, 9.8, 4.87) in her frame → feet 4.87 behind the towel
401	    const feetW = new THREE.Vector3(P0.center.x, P0.topY + 2.55 - 9.8, P0.center.z - 3.4 - 4.87);
402	    const feetL = env.roomC.anchor.worldToLocal(feetW.clone());
403	    if (t < O.lean0) {
404	      const from = env.roomC.spots.table.clone();
405	      const k = sm(0.0, O.lean0 - 0.15, t);
406	      placeGirl('C', from.lerp(feetL, k), lerp(0.25, Math.PI, sm(0, 0.7, t)));
407	      girl.play(k < 0.97 ? 'walk' : 'idle', { fade: 0.3 });
