// scratch: render the tube from a reference-like ON-AXIS camera (independent of the ride camera work).
// node axcap.mjs OUTDIR "query" s1 s2 ...  (cwd = repo). Writes OUTDIR/ax_<s>.png
import { mkdirSync } from 'node:fs';
import { loadPlaywright, CHROMIUM_ARGS, startVite } from '/home/user/rainbow-/scripts/lib/pw.mjs';
const [outDir, q, ...ss] = process.argv.slice(2);
mkdirSync(outDir, { recursive: true });
const { chromium } = loadPlaywright();
const vite = await startVite(5233);
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
try {
  const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
  const errs = [];
  page.on('pageerror', (e) => errs.push(e.message));
  await page.route('**/src/game/Game.ts*', async (route) => {
    const resp = await route.fetch();
    let body = await resp.text();
    body = body.replace(/(const camera = new THREE\.PerspectiveCamera\([^;]*;)/, '$1 window.__cam = camera;');
    body = body.replace(/(const env = buildEnvironment\(course\);)/, '$1 window.__env = env;');
    body = body.replace(/(const render = \(\) => \{[^}]*\};)/, '$1 window.__render = render;');
    await route.fulfill({ response: resp, body });
  });
  await page.goto(`${vite.url}/?qa=1&dpr=1${q ? '&' + q : ''}`);
  await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 240000 });
  for (const sArg of ss) {
    const [sRel, hgt = '2.6', ahead = '30', stage = '05'] = sArg.split(':');
    const info = await page.evaluate(({ sRel, hgt, ahead, stage }) => {
      const R = window.__rainbow;
      R.goto(stage);
      const ax = window.__env.tubeAxis.path;
      const s0 = R.course.stage(stage).s0 + Number(sRel);
      const f = ax.frame(s0);
      const cam = window.__cam;
      const c = f.pos.clone().addScaledVector(f.up, ax.radius(s0) - ax.depth(s0));
      // camera: on the tube axis horizontally, `hgt` above the water level
      const p = f.pos.clone().addScaledVector(f.up, Number(hgt));
      const fa = ax.frame(s0 + Number(ahead));
      const look = fa.pos.clone().addScaledVector(fa.up, Number(hgt) * 0.55);
      cam.position.copy(p);
      cam.up.set(0, 1, 0);
      cam.lookAt(look);
      cam.fov = 66; cam.updateProjectionMatrix();
      window.__render();
      return { r: ax.radius(s0), depth: ax.depth(s0), center: c.toArray().map((v) => +v.toFixed(2)) };
    }, { sRel, hgt, ahead, stage });
    await page.waitForTimeout(150);
    await page.screenshot({ path: `${outDir}/ax_${stage}_${sRel}.png` });
    const stats = await page.evaluate(() => window.__rainbow.stats());
    console.log(sArg, JSON.stringify(info), 'calls', stats.calls, 'tris', stats.triangles);
  }
  if (errs.length) console.log('errors', errs.slice(0, 5));
} finally {
  await browser.close();
  await vite.close();
}

